// Stages the generated proxy files @cratis/chronicle-ui compiles against.
//
// The Chronicle proxy generator writes into Features/ (see README.md, "Regenerating Workbench proxies").
// The UI package must not reach into the app at build or run time, so this copies - unmodified - exactly the
// two generated files its event store names hook needs into an ignored build-input directory of the package.
// Nothing is rewritten and nothing staged is committed; a missing, hand-edited or unmarked file fails the build.

import { cpSync, existsSync, mkdirSync, readFileSync, rmSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const workbench = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const source = path.join(workbench, 'Features', 'EventStores');
const target = path.join(workbench, 'packages', 'chronicle-ui', 'generated-input', 'EventStores');

const allowlist = ['ObserveEventStores.ts', 'EventStoreNames.ts'];
const generatedMarker = '// @generated by Cratis';

export const stage = (sourceDirectory = source, targetDirectory = target) => {
    for (const file of allowlist) {
        const from = path.join(sourceDirectory, file);
        if (!existsSync(from)) {
            throw new Error(`Generated proxy ${from} is missing. Regenerate the Workbench proxies (Source/Workbench/README.md).`);
        }
        const content = readFileSync(from, 'utf8');
        if (!content.split('\n').slice(0, 10).some(line => line.startsWith(generatedMarker))) {
            throw new Error(`${from} does not carry the "${generatedMarker}" marker; the UI package only stages generated proxies.`);
        }
        for (const [, specifier] of content.matchAll(/from '(\.[^']*)'/g)) {
            if (!allowlist.includes(`${path.basename(specifier)}.ts`)) {
                throw new Error(`${from} imports ${specifier}, which is outside the staged set (${allowlist.join(', ')}).`);
            }
        }
    }

    rmSync(targetDirectory, { recursive: true, force: true });
    mkdirSync(targetDirectory, { recursive: true });
    for (const file of allowlist) {
        cpSync(path.join(sourceDirectory, file), path.join(targetDirectory, file));
    }
};

if (process.argv[1] === fileURLToPath(import.meta.url)) {
    stage();
    console.log(`Staged ${allowlist.length} generated proxies into ${path.relative(workbench, target)}`);
}
